import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Fragment,
	Host,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";

import { caretDoubleLeft, caretDoubleRight } from "../../../icons";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { hasSlot } from "../../utils/slot";

interface I18n {
	previousYear?: string;
	nextYear?: string;
	months?: string[];
	quarters?: string[];
}

/**
 * @since 2.4.0
 * @status stable
 *
 * @data-testid prevYear - The previous-year navigation control.
 * @data-testid nextYear - The next-year navigation control.
 * @data-testid year-button-{year} - A year option button, where `{year}` is the rendered year value.
 * @data-testid month-button-{month} - A month option button, where `{month}` is the rendered month value.
 * @data-testid quarter-button-{quarter} - A quarter option button, where `{quarter}` is the rendered quarter value.
 *
 * @part base - The component's base wrapper.
 * @part header - The header of the month component.
 * @part year - The year part of the month component.
 * @part body - The wrapper for the months / quarters / years.
 *
 * @slot previous-year - The slot for the previous year button.
 * @slot year - The slot for the year.
 * @slot next-year - The slot for the next year button.
 * @slot - The slot for the months / quarters / years.
 *
 */

@Component({
	tag: "hbr-picker",
	styleUrl: "picker.scss",
	shadow: true,
})
export class HbrPicker {
	@Element() host: HTMLHbrPickerElement;

	/** i18n for localization and accessibility. */
	@Prop() i18n: I18n = {
		months: [
			"January",
			"February",
			"March",
			"April",
			"May",
			"June",
			"July",
			"August",
			"September",
			"October",
			"November",
			"December",
		],
		quarters: ["Q1", "Q2", "Q3", "Q4"],
		previousYear: "Click to go to the previous year.",
		nextYear: "Click to go to the next year.",
	};

	/** An array of months, quarters, or years. The i18n object can be used to replace this. */
	@Prop({ mutable: true }) data:
		| string[]
		| number[]
		| {
				year: number;
				disabled: boolean;
		  }[];

	/** String of disabled months from 1-12 and year in "Mon YYYY" format. 'Mon' should match to months array values */
	@Prop({ reflect: true, mutable: true }) selected: string;

	/** Indicate a type of the pickers. */
	@Prop({ reflect: true, mutable: true }) variant: "month" | "quarter" | "year"; //no default since we want picker to be flexible not limited to these 3

	/** Number of years on either side, or an array specifying the upper and lower range when the variant is set exclusively to 'year'. since v2.9.17 */
	@Prop({ reflect: true }) yearRange?: number | number[];

	/** Year prop for storing year */
	@Prop({ reflect: true, mutable: true }) year: number | string;

	/** Value prop for storing value */
	@Prop({ reflect: true, mutable: true }) value: string | number;

	/** Array of disabled values */
	@Prop({ mutable: true }) disabled: (number | string)[];

	/** Disable previous year arrow icon */
	@Prop({ reflect: true, mutable: true }) disablePrevious: boolean;

	/** Disable next year arrow icon */
	@Prop({ reflect: true, mutable: true }) disableNext: boolean;

	/** Set minimum year to disable the left arrow for the year or year range. since v2.9.17 */
	@Prop({ reflect: true }) minYear: number;

	/** Set maximum year to disable the right arrow for the year or year range. since v2.9.17 */
	@Prop({ reflect: true }) maxYear: number;

	@State() selectedValue: string;

	@State() hasHeaderSlot: boolean;

	@Watch("disabled")
	handleDisabledChange() {
		this.host.setAttribute("aria-disabled", this.disabled ? "true" : "false");
	}

	/** Emitted when clicking the button. */
	@Event({ eventName: "hbr-click" }) hbrClick: EventEmitter;

	/** Emitted when clicking the previous year arrow. */
	@Event({ eventName: "hbr-previous-year" }) hbrPreviousYear: EventEmitter<{
		year?: number | string;
		event?: MouseEvent;
	}>;

	/** Emitted when clicking the next year arrow. */
	@Event({ eventName: "hbr-next-year" }) hbrNextYear: EventEmitter<{
		year?: number | string;
		event?: MouseEvent;
	}>;

	@Event({ eventName: "hbr-year-heading-click" })
	hbrYearHeadingClick: EventEmitter<{
		year: number | string;
	}>;

	setVariant() {
		if (!this.variant) {
			// Ensure variant is set for angular
			const { year } = this;
			if (year && typeof year === "string" && year.includes("-")) {
				// "2020-2029"
				this.variant = "year";
			} else if (this.data?.length === 12) {
				const firstData = this.data[0];

				if (
					typeof firstData === "string" &&
					this.i18n.months[0].includes(firstData)
				) {
					this.variant = "month";
				}
			}
		}
	}

	connectedCallback() {
		const { variant, i18n } = this;
		this.handleSlotChange = this.handleSlotChange.bind(this);

		if (!this.data) {
			if (variant === "month") {
				this.data = i18n.months;
			} else if (variant === "quarter") {
				this.data = i18n.quarters;
			} else if (
				(variant === "year" && !this.yearRange) ||
				this.yearRange === 10
			) {
				this.data = Array.from({ length: 12 }, (_, i) => i + 1);
			}
		}
		this.setVariant();
	}

	componentWillLoad() {
		this.setVariant();
	}

	handleSlotChange() {
		this.hasHeaderSlot = hasSlot(this.host, "header");
	}

	handlePrevYearClick(event: MouseEvent) {
		this.year = String(Number(this.year) - 1);
		this.hbrPreviousYear.emit({ year: Number(this.year), event });
	}
	handleNextYearClick(event: MouseEvent) {
		this.year = String(Number(this.year) + 1);
		this.hbrNextYear.emit({ year: Number(this.year), event });
	}
	handlePrevYearRangeClick(event: MouseEvent) {
		let filteredData: (
			| string
			| number
			| { year: number | string; disabled: boolean }
		)[];
		if (typeof this.data[0] === "object") {
			filteredData = this.data
				.filter((d: { year: number; disabled: boolean }) => !d.disabled)
				.map((d) => (typeof d === "object" ? Number(d.year) : d));
		} else {
			filteredData = this.data.filter((year: number) =>
				this.disabled?.length ? !this.disabled.includes(year) : true,
			);
		}
		const currentStartYear = Number(filteredData[0]);
		const prevEndYear = currentStartYear - 1;
		const prevStartYear = prevEndYear - 9;

		this.data = Array.from({ length: 12 }, (_, i) => {
			const currentYear = prevStartYear - 1 + i;
			return {
				year: currentYear,
				disabled: currentYear < prevStartYear || currentYear > prevEndYear,
			};
		});
		this.disabled = this.data
			.filter((d: { year: number; disabled: boolean }) => d.disabled)
			.map((d) => d.year);
		this.year = `${prevStartYear}-${prevEndYear}`;
		this.hbrPreviousYear.emit({ year: this.year, event });
	}
	handleNextYearRangeClick(event: MouseEvent) {
		let filteredData: (
			| string
			| number
			| { year: number | string; disabled: boolean }
		)[];
		if (typeof this.data[0] === "object") {
			filteredData = this.data
				.filter((d: { year: number; disabled: boolean }) => !d.disabled)
				.map((d) => (typeof d === "object" ? Number(d.year) : d));
		} else {
			filteredData = this.data.filter((year: number) =>
				this.disabled?.length ? !this.disabled.includes(year) : true,
			);
		}

		const currentEndYear =
			(filteredData?.length ?? 0) &&
			Number(filteredData[filteredData.length - 1]);

		const nextStartYear = currentEndYear + 1;
		const nextEndYear = nextStartYear + 9;

		this.data = Array.from({ length: 12 }, (_, i) => {
			const currentYear = nextStartYear - 1 + i;
			return {
				year: currentYear,
				disabled: currentYear < nextStartYear || currentYear > nextEndYear,
			};
		});

		this.disabled = this.data
			.filter((d: { year: number; disabled: boolean }) => d.disabled)
			.map((d) => d.year);
		this.year = `${nextStartYear}-${nextEndYear}`;

		this.hbrNextYear.emit({ year: this.year, event });
	}
	handleButtonClick(
		value: number | undefined,
		month: number,
		event: MouseEvent,
	) {
		this.hbrClick.emit({
			value,
			event,
			month,
			data: this.data,
			year: this.year,
		});
	}
	handleYearHeader() {
		this.hbrYearHeadingClick.emit({ year: Number(this.year) });
	}

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		if (!this.data || this.data.length === 0) {
			return null;
		}

		let yearRangeLabel = "";
		if (this.variant === "year") {
			if (typeof this.data[0] === "object") {
				const validYearsArray = this.data.filter(
					(d): d is { year: number; disabled: boolean } =>
						typeof d === "object" && !d.disabled,
				);
				yearRangeLabel = `${validYearsArray[0].year}-${
					validYearsArray[validYearsArray.length - 1].year
				}`;
			} else {
				const filteredData = this.data.filter(
					(year: number) => !this.disabled || !this.disabled.includes(year),
				);
				yearRangeLabel = `${filteredData[0]}-${
					filteredData[filteredData.length - 1]
				}`;
			}
		}

		const nextYearArrowDisable =
			Number(this.year) ===
			(this.disabled?.length &&
				this.disabled.length > 1 &&
				Number(this.disabled[1]) - 1);

		return (
			<Host>
				<div part="base" class={"picker"}>
					<div class={"header"} part="header">
						{this.hasHeaderSlot ? (
							<slot name="header" onSlotchange={this.handleSlotChange} />
						) : (
							<Fragment>
								<slot name="previous-year" onSlotchange={this.handleSlotChange}>
									{this.variant === "month" || this.variant === "quarter" ? (
										<hbr-icon-button
											data-testid="prevYear"
											asset={
												customSystemIcons?.["caret-double-left"] ||
												caretDoubleLeft
											}
											onClick={this.handlePrevYearClick.bind(this)}
											class={"picker__prev-year"}
											aria={{
												label:
													this.i18n.previousYear ||
													"Click to go to the previous year.",
											}}
											size={"12px"}
											disabled={Number(this.year) - 1 === this.minYear}
										/>
									) : (
										<hbr-icon-button
											data-testid="prevYear"
											asset={
												customSystemIcons?.["caret-double-left"] ||
												caretDoubleLeft
											}
											onClick={this.handlePrevYearRangeClick.bind(this)}
											class={"picker__prev-year"}
											aria={{
												label:
													this.i18n.previousYear ||
													"Click to go to the previous year.",
											}}
											size={"12px"}
										/>
									)}
								</slot>
								{this.variant === "month" || this.variant === "quarter" ? (
									<span
										part="year"
										role="button"
										tabindex="0"
										onClick={this.handleYearHeader.bind(this)}
									>
										<slot name="year" onSlotchange={this.handleSlotChange}>
											{this.year}
										</slot>
									</span>
								) : (
									<span part="year">
										<slot name="year" onSlotchange={this.handleSlotChange}>
											{yearRangeLabel}
										</slot>
									</span>
								)}
							</Fragment>
						)}

						<slot name="next-year" onSlotchange={this.handleSlotChange}>
							{this.variant === "month" || this.variant === "quarter" ? (
								<hbr-icon-button
									asset={
										customSystemIcons?.["caret-double-right"] ||
										caretDoubleRight
									}
									arialabel={
										this.i18n.nextYear || "Click to go to the next year."
									}
									data-testid="nextYear"
									class={"picker__next-year"}
									onClick={this.handleNextYearClick.bind(this)}
									size={"12px"}
									disabled={nextYearArrowDisable}
								/>
							) : (
								<hbr-icon-button
									asset={
										customSystemIcons?.["caret-double-right"] ||
										caretDoubleRight
									}
									arialabel={
										this.i18n.nextYear || "Click to go to the next year."
									}
									data-testid="nextYear"
									class={"picker__next-year"}
									onClick={this.handleNextYearRangeClick.bind(this)}
									size={"12px"}
									disabled={nextYearArrowDisable}
								/>
							)}
						</slot>
					</div>
					<div class={`picker__body ${this.variant}`} part="body">
						<slot>
							{this.data.map(
								(
									_d: number | string | { year: number; disabled: boolean },
									index: number,
								) => {
									let buttonDisabled: boolean;
									if (typeof _d === "object") {
										//for now, year picker only
										const { year, disabled } = _d;
										buttonDisabled = disabled;

										return (
											<button
												type="button"
												data-testid={`year-button-${year}`}
												key={index.toString()}
												value={year}
												class={{
													/** type of picker */
													picker__month: this.variant === "month",
													picker__year: this.variant === "year",
													picker__quarter: this.variant === "quarter",

													picker__button: true,
													picker__selected:
														(!disabled && this.value === year) ||
														this.value === index,
													picker__disabled: disabled,
												}}
												disabled={
													buttonDisabled ||
													(this.disabled?.length &&
														this.disabled.includes(year))
												}
												onClick={
													!disabled &&
													this.handleButtonClick.bind(
														this,
														year,
														this.variant === "month" ? index : undefined,
													)
												}
											>
												{year}
											</button>
										);
									}

									buttonDisabled =
										this.disabled?.length && this.disabled.includes(_d);

									return (
										<button
											type="button"
											data-testid={
												this.variant === "quarter"
													? `quarter-button-${_d}`
													: this.variant === "year"
													  ? `year-button-${_d}`
													  : `month-button-${_d}`
											}
											key={index.toString()}
											value={_d}
											{...(this.variant === "month" && {
												"data-month": index,
											})}
											class={{
												/** type of picker */
												picker__month: this.variant === "month",
												picker__year: this.variant === "year",
												picker__quarter: this.variant === "quarter",

												picker__button: true,
												picker__selected:
													(!buttonDisabled && this.value === _d) ||
													this.value === index,
												picker__disabled: buttonDisabled,
											}}
											disabled={buttonDisabled}
											onClick={
												!buttonDisabled &&
												this.handleButtonClick.bind(
													this,
													_d,
													this.variant === "month" ? index : undefined,
												)
											}
										>
											{this.variant === "month" ? (
												<abbr title={this.i18n.months[index]}>{_d}</abbr>
											) : (
												_d
											)}
										</button>
									);
								},
							)}
						</slot>
					</div>
				</div>
			</Host>
		);
	}
}
